struct VSOut { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; };

float4 PSScene(VSOut i) : SV_Target
{
    float2 uv = i.uv;
    float t = time_sim_ms * 0.001;
    float3 color = float3(0.1, 0.1, 0.15);
    float2 c1 = float2(0.3 + 0.1 * sin(t), 0.5);
    float2 c2 = float2(0.7 - 0.1 * cos(t * 0.8), 0.5);
    if (length(uv - c1) < 0.15) color = float3(0.9, 0.3, 0.2);
    if (length(uv - c2) < 0.12) color = float3(0.2, 0.6, 0.9);
    return float4(color, 1.0);
}

