[[vk::combinedImageSampler]] [[vk::binding(0, 2)]]
Texture2D sceneTex : register(t0, space2);
[[vk::combinedImageSampler]] [[vk::binding(0, 2)]]
SamplerState sceneSamp : register(s0, space2);

struct VSOut { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; };

float luminance(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }

float4 PSEdge(VSOut i) : SV_Target
{
    float2 uv = i.uv;
    float2 texel = 1.0 / float2(resolution_x, resolution_y);

    float tl = luminance(sceneTex.Sample(sceneSamp, uv + float2(-texel.x, -texel.y)).rgb);
    float t  = luminance(sceneTex.Sample(sceneSamp, uv + float2(0, -texel.y)).rgb);
    float tr = luminance(sceneTex.Sample(sceneSamp, uv + float2(texel.x, -texel.y)).rgb);
    float l  = luminance(sceneTex.Sample(sceneSamp, uv + float2(-texel.x, 0)).rgb);
    float r  = luminance(sceneTex.Sample(sceneSamp, uv + float2(texel.x, 0)).rgb);
    float bl = luminance(sceneTex.Sample(sceneSamp, uv + float2(-texel.x, texel.y)).rgb);
    float b  = luminance(sceneTex.Sample(sceneSamp, uv + float2(0, texel.y)).rgb);
    float br = luminance(sceneTex.Sample(sceneSamp, uv + float2(texel.x, texel.y)).rgb);

    float gx = -tl - 2.0*l - bl + tr + 2.0*r + br;
    float gy = -tl - 2.0*t - tr + bl + 2.0*b + br;
    float edge = sqrt(gx*gx + gy*gy);

    float3 scene = sceneTex.Sample(sceneSamp, uv).rgb;
    float3 glowColor = float3(0.0, 1.0, 0.5) * edge * 3.0;
    float3 color = scene + glowColor;
    return float4(color, 1.0);
}
